INSERT OR IGNORE INTO cms_content (content_key, value_ar, value_en) VALUES
  ('hero_text', 'شريككم الموثوق لتوريد وتوزيع منتجات الدواجن في مختلف أنحاء قطر. حلول مرنة، وخيارات متنوعة، وقيمة تنافسية لأعمالكم.', 'Your reliable partner for poultry products supply and distribution across Qatar. Flexible solutions, diverse product options, and competitive value for your business.'),
  ('home_intro_title', 'توريد يدعم نمو أعمالكم.', 'Supply that moves your business forward.'),
  ('advantages_title', 'شريك توريد يبدأ من احتياجاتكم', 'A supply partner built around your needs'),
  ('advantages_text', 'خيارات أكثر وكميات مرنة وتوريد يراعي القيمة، مع نقطة تواصل واحدة تستجيب لاحتياجاتكم.', 'More choice, flexible quantities and value-focused sourcing — with one responsive point of contact.'),
  ('advantage_1_title', 'تنوع المنتجات', 'Product variety'),
  ('advantage_1_description', 'خيارات متعددة من منتجات الدواجن والموردين.', 'A broad choice of poultry products and supplier options.'),
  ('advantage_2_title', 'قيمة تنافسية', 'Competitive value'),
  ('advantage_2_description', 'خيارات توريد تساعد في إدارة تكاليف التشغيل.', 'Supply options designed to help manage operating costs.'),
  ('advantage_3_title', 'توريد مرن', 'Flexible supply'),
  ('advantage_3_description', 'مناقشة الكميات والاختيارات وفق متطلباتكم.', 'Quantities and selections discussed around your requirements.'),
  ('advantage_4_title', 'خدمة في قطر', 'Qatar-wide service'),
  ('advantage_4_description', 'دعم العملاء من الشركات في مختلف أنحاء دولة قطر.', 'Support for business customers across the State of Qatar.'),
  ('home_products_title', 'مجموعة المنتجات', 'Product range'),
  ('home_products_text', 'مجموعة متنوعة من منتجات الدواجن، مع خيارات يمكن مناقشتها وفق متطلبات أعمالكم.', 'A focused selection of poultry products, with options to discuss around your business requirements.'),
  ('home_brands_title', 'خيارات من شبكة موردين موثوقة', 'Choice across trusted suppliers'),
  ('home_brands_text', 'نعمل مع شبكة واسعة من العلامات التجارية والموردين. أخبرونا بما تحتاجه أعمالكم لنناقش الخيارات المتاحة.', 'We work with a wide network of brands and suppliers. Tell us what your operation needs and our team can discuss available options.'),
  ('sectors_title', 'القطاعات التي نخدمها', 'Who we serve'),
  ('sector_1_title', 'المطاعم', 'Restaurants'),
  ('sector_1_description', 'خيارات توريد موثوقة للمطابخ العاملة بوتيرة سريعة.', 'Reliable supply options for busy kitchens.'),
  ('sector_2_title', 'الفنادق', 'Hotels'),
  ('sector_2_description', 'تنوع المنتجات لدعم عمليات الضيافة.', 'Product choice to support hospitality operations.'),
  ('sector_3_title', 'السوبرماركت', 'Supermarkets'),
  ('sector_3_description', 'فئات متعددة من منتجات الدواجن لاحتياجات البيع بالتجزئة.', 'A range of poultry categories for retail needs.'),
  ('sector_4_title', 'تجار الجملة والتموين', 'Wholesalers & foodservice'),
  ('sector_4_description', 'توريد مرن للاحتياجات الكبيرة والمتكررة.', 'Flexible sourcing for bulk and recurring requirements.'),
  ('coverage_title', 'نخدم الأعمال في مختلف أنحاء قطر', 'Serving businesses across Qatar'),
  ('coverage_text', 'نسعى لخدمة العملاء في مختلف مناطق دولة قطر. تواصلوا مع فريقنا لمناقشة ترتيبات التوصيل لموقعكم.', 'We aim to support customers across the State of Qatar. Contact our team to discuss delivery arrangements for your location.'),
  ('cta_title', 'لنضع خطة توريد أفضل لأعمالكم.', 'Let’s build a better supply plan.'),
  ('cta_text', 'أخبرونا عن نشاطكم والمنتجات التي تحتاجونها والكميات التي تخططون لها.', 'Tell us about your business, the products you need and the quantities you are planning for.'),
  ('faq_preview_title', 'إجابات عن أسئلتكم.', 'Questions, answered.'),
  ('footer_text', 'توريد مرن. قيمة تنافسية.', 'Flexible supply. Competitive value.'),
  ('about_title', 'شريك توريد يعتمد عليه لقطاع الأغذية في قطر.', 'A dependable supply partner for Qatar’s food businesses.'),
  ('about_intro', 'تورّد وفرة الريف منتجات الدواجن للأعمال التي تقدّر تنوع الخيارات ومرونة التوريد وسرعة الاستجابة.', 'Wafrat Al Reef supplies poultry products to businesses that value choice, flexible sourcing and responsive service.'),
  ('about_approach_title', 'شراكة تجارية تبدأ بفهم احتياجاتكم.', 'Partnership begins by understanding your needs.'),
  ('about_approach_text', 'نعمل على بناء علاقات طويلة الأمد مع المطاعم والفنادق والسوبرماركت وتجار الجملة، من خلال حلول توريد مرنة وموثوقة تدعم نجاح أعمالهم.', 'We work to build long-term relationships with restaurants, hotels, supermarkets and wholesalers through flexible, reliable supply solutions that support their business.'),
  ('products_page_title', 'منتجات دواجن لتوريد الأعمال.', 'Poultry products for business supply.'),
  ('products_page_text', 'تعرّفوا على فئات المنتجات واطلبوا معلومات وفق احتياجات أعمالكم. يمكن مناقشة التوافر والكميات مع فريقنا.', 'Browse our supply categories and request information based on your business needs. Product availability and quantities can be discussed with our team.'),
  ('brands_page_title', 'خيارات متنوعة لتلبية احتياجات التوريد.', 'A network of options for your supply needs.'),
  ('brands_page_text', 'نعمل مع شبكة واسعة من العلامات التجارية والموردين. أخبرونا بما تحتاجه أعمالكم لنناقش الخيارات المتاحة.', 'We work with a wide network of brands and suppliers. Tell us what your operation needs and our team can discuss available options.'),
  ('brands_empty_title', 'خيارات متعددة. احتياجات مختلفة.', 'More choice. Different needs.'),
  ('brands_empty_text', 'ستُضاف العلامات التجارية للموردين بعد اعتمادها للنشر.', 'Supplier brands will be added here as they are approved for publication.'),
  ('why_title', 'شريك يفهم احتياجات توريد الأعمال.', 'A partner that understands business supply.'),
  ('why_text', 'من تنوع المنتجات إلى تنسيق التوريد الموثوق، نعمل بما يساعد أعمالكم على الاستمرار والنمو.', 'From product variety to dependable coordination, our approach is built around what helps your operation run well.'),
  ('faq_title', 'الأسئلة الشائعة', 'Frequently asked questions'),
  ('faq_intro', 'إجابات واضحة عن التوريد والمنتجات والتواصل مع وفرة الريف.', 'Clear answers about supply, products and working with Wafrat Al Reef.'),
  ('meeting_title', 'لنتحدث عن احتياجات التوريد لديكم.', 'Let’s talk about your supply needs.'),
  ('meeting_text', 'شاركوا معنا بعض التفاصيل عن أعمالكم، وسيتواصل فريقنا لمناقشة المنتجات والكميات المناسبة.', 'Share a few details about your business. Our team will get in touch to discuss suitable products and quantities.'),
  ('meeting_aside_title', 'احتياجاتكم أولويتنا.', 'Your requirements come first.'),
  ('meeting_aside_text', 'شاركنا المعلومات الأساسية، وسنعود إليكم لمناقشة الأنسب لعملكم.', 'Share a few details and our team will get back to discuss what works for your operation.'),
  ('contact_title', 'تواصلوا مع فريقنا.', 'Talk to our team.'),
  ('contact_text', 'لاستفسارات التوريد أو معلومات المنتجات أو فرص الشراكة، يسعدنا تواصلكم عبر التفاصيل أدناه.', 'For supply enquiries, product information or partnership conversations, reach us through the details below.'),
  ('contact_aside_title', 'لنتحدث عن احتياجات أعمالكم.', 'Let’s discuss your business needs.'),
  ('value_1_title', 'الجودة', 'Quality'),
  ('value_1_description', 'الالتزام بجودة المنتجات ومعايير سلامة الغذاء.', 'Commitment to product quality and food safety standards.'),
  ('value_2_title', 'الثقة', 'Trust'),
  ('value_2_description', 'بناء علاقات تجارية قائمة على المصداقية والشفافية.', 'Building business relationships based on credibility and transparency.'),
  ('value_3_title', 'الاعتمادية', 'Reliability'),
  ('value_3_description', 'الالتزام بالتوريد في المواعيد المحددة واستمرارية الإمداد.', 'Ensuring timely deliveries and consistent supply.'),
  ('value_4_title', 'الشراكة', 'Partnership'),
  ('value_4_description', 'فهم احتياجات العملاء والعمل على نجاح أعمالهم.', 'Understanding our customers'' needs and contributing to their business success.'),
  ('value_5_title', 'الوفرة', 'Abundance'),
  ('value_5_description', 'توفير خيارات متنوعة تلبي احتياجات مختلف قطاعات السوق بالكميات المطلوبة.', 'Offering a wide variety of options to meet the needs and quantity requirements of different market sectors.'),
  ('value_6_title', 'التوفير', 'Savings'),
  ('value_6_description', 'مقارنة بالخيارات الأخرى في السوق، تعمل وفرة الريف على تقليل تكاليف أعمالكم.', 'Compared with other available market options, Wafrat Al Reef works to help reduce your business costs.');
